import{_ as t,o,c as a,ae as n}from"./chunks/framework.B2FZg54p.js";const s="/heidrun/experiments/web-doc-by-ai/documentation_images/change_window_font_size/settings.svg",i="/heidrun/experiments/web-doc-by-ai/documentation_images/change_window_font_size/command_palette.svg",p=JSON.parse('{"title":"Change the window font size","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/change_window_font_size.md","filePath":"documentation/change_window_font_size.md"}'),r={name:"documentation/change_window_font_size.md"};function h(l,e,d,c,m,g){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="change-the-window-font-size" tabindex="-1">Change the window font size <a class="header-anchor" href="#change-the-window-font-size" aria-label="Permalink to &quot;Change the window font size&quot;">​</a></h1><p>Change the size of text across the Heidrun window, including terminal output, and restore the default size when needed.</p><h2 id="change-the-window-font-size-1" tabindex="-1">Change the window font size <a class="header-anchor" href="#change-the-window-font-size-1" aria-label="Permalink to &quot;Change the window font size&quot;">​</a></h2><ol><li>At the top-right of the window, select <strong>More actions</strong>, then select <strong>Settings</strong>.</li><li>In Settings, select <strong>Terminal</strong>.</li><li>Select <strong>Increase the font size</strong> (A+) or <strong>Decrease the font size</strong> (A−) beside the size value; the change applies immediately to the whole Heidrun window, including terminal output.</li><li>Select <strong>Close</strong> or press Escape to close Settings.</li></ol><p><img src="'+s+'" alt="Settings with the size controls and Reset highlighted"></p><h2 id="restore-the-default-size" tabindex="-1">Restore the default size <a class="header-anchor" href="#restore-the-default-size" aria-label="Permalink to &quot;Restore the default size&quot;">​</a></h2><p>In Settings → Terminal, select <strong>Reset</strong> to return to the default size of 16 px. You can also choose <strong>Default font size</strong> from the command palette.</p><h2 id="use-a-shortcut-or-the-command-palette" tabindex="-1">Use a shortcut or the command palette <a class="header-anchor" href="#use-a-shortcut-or-the-command-palette" aria-label="Permalink to &quot;Use a shortcut or the command palette&quot;">​</a></h2><p>Use <strong>Command+Plus</strong> to increase the size, <strong>Command+Minus</strong> to decrease it, or <strong>Command+0</strong> to restore the default. You can also open the command palette with <strong>Command+K</strong> and select <strong>Increase the font size</strong>, <strong>Decrease the font size</strong>, or <strong>Default font size</strong>.</p><p><img src="'+i+'" alt="The command palette with its named font-size actions highlighted below the separate Run commands"></p><p>When searching in the command palette, choose one of the named font-size actions; the separate <strong>Run</strong> commands run text as a terminal command.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><section class="documentation-troubleshooting-topic" aria-label="A size button is disabled"><h3 id="a-size-button-is-disabled" tabindex="-1">A size button is disabled <a class="header-anchor" href="#a-size-button-is-disabled" aria-label="Permalink to &quot;A size button is disabled&quot;">​</a></h3><p><strong>Cause</strong>: The size is already at its limit of 9 px or 24 px.</p><p><strong>Solution</strong>:</p><ol><li>Select the opposite size button to move away from the limit, or select <strong>Reset</strong> to return to 16 px.</li></ol><p><strong>Check</strong>: The displayed size changes, and the size button that was disabled becomes available.</p></section><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/shortcuts.html">Keyboard shortcuts</a>: to find other keyboard commands.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/split_and_resize_panes.html">Split and resize panes</a>: to change the space available to each terminal.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/tabs.html">Create, select and rename tabs</a>: to move between tabs.</li></ul>',15)])])}const f=t(r,[["render",h]]);export{p as __pageData,f as default};
